 void RenderTargets(){if(targets==null)return;targets.Children.Clear();string filter=search==null?"":search.Text.Trim().ToLowerInvariant();var filtered=routes.Where(r=>r.Format.Contains(filter)||r.Description.ToLowerInvariant().Contains(filter)).ToList();
  if(filter==""&&!showAll){string key=files.Length==0?"":(Backend.Detect(files[0])==null?"":Backend.Detect(files[0]).Category);var popular=new Dictionary<string,string>{{"Image","png jpg webp avif ico pdf"},{"Pdf","docx png jpg txt pdf pptx"},{"Document","pdf docx txt html epub"},{"Spreadsheet","xlsx csv json pdf html ods"},{"Presentation","pdf png jpg docx"},{"Video","mp4 mov mkv webm gif mp3"},{"Audio","mp3 wav flac m4a ogg opus"},{"Cad","dwg dxf pdf svg png"},{"Font","ttf otf woff woff2 eot"},{"Data","json yaml toml xml csv xlsx"},{"Archive","extract zip 7z tar tgz"},{"Ebook","epub pdf docx txt mobi azw3"},{"Model3D","glb gltf obj stl ply 3mf"},{"Geo","geojson kml kmz gpx csv xlsx"},{"Text","pdf docx txt html epub"},{"Subtitle","srt ass vtt lrc"},{"Vector","svg png pdf jpg dxf"}};string order=popular.ContainsKey(key)?popular[key]:"png jpg webp pdf docx txt zip extract";var common=order.Split(' ');filtered=filtered.Where(r=>common.Contains(r.Format)).OrderBy(r=>Array.IndexOf(common,r.Format)).ToList();if(filtered.Count==0)filtered=routes.Take(6).ToList();}
  foreach(var group in filtered.GroupBy(r=>Backend.Group(r.Format))){var label=Text(group.Key,10,"#8B9BB3");label.Width=400;label.Margin=new Thickness(0,10,0,8);targets.Children.Add(label);foreach(var r in group){string f=r.Format;var button=Button(f=="extract"?"解压":f.ToUpperInvariant(),()=>Start(f));button.Width=91;button.Height=42;button.Margin=new Thickness(0,0,8,8);button.ToolTip=r.Description+" · "+r.Engine;button.AllowDrop=true;button.DragOver+=(s,e)=>{e.Effects=DragDropEffects.Copy;e.Handled=true;};button.Drop+=(s,e)=>{e.Handled=true;Start(f);};targets.Children.Add(button);}}
  if(filtered.Count==0)targets.Children.Add(Text("没有匹配的转换路线。未知格式仍可压缩保存。",12,"#8B9BB3"));
  if(filter==""&&routes.Count>filtered.Count){var more=Button("显示全部可用格式  ·  "+routes.Count,()=>{showAll=true;RenderTargets();});more.Width=390;more.Margin=new Thickness(0,14,0,0);targets.Children.Add(more);}else if(showAll&&filter==""){var less=Button("收起，只看常用格式",()=>{showAll=false;RenderTargets();});less.Width=390;targets.Children.Add(less);}
