 public async void Start(string format){if(running||files.Length==0)return;running=true;selected=format;cancel=new CancellationTokenSource();outputs.Clear();if(!expanded){Anchor(500,640);expanded=true;}Frame("正在流转…",files.Length+" 个文件 → "+format.ToUpperInvariant());bar=new ProgressBar(){Minimum=0,Maximum=100,Height=7,Foreground=Brush("#528AF1"),Background=Brush("#EAF0F9"),BorderThickness=new Thickness(0),Margin=new Thickness(0,25,0,16)};body.Children.Add(bar);var state=Text("正在准备任务",13,"#617493");body.Children.Add(state);stop=Button("取消本次转换",()=>{cancel.Cancel();stop.IsEnabled=false;state.Text="正在取消并清理…";});stop.Margin=new Thickness(0,20,0,0);body.Children.Add(stop);var token=cancel.Token;
  try{CoreResult result;if(Backend.Ready&&(files.All(f=>Backend.Detect(f)!=null)||new[]{"zip","7z","tar","tgz"}.Contains(format))&&format!="gz"){
    result=await Task.Run(()=>Backend.Convert(files,format,owner.Pref,recipe,token,value=>Dispatcher.BeginInvoke(new Action(()=>{bar.Value=value*100;state.Text="已处理 "+(value*100).ToString("0")+"%";}))));
   }else{var rows=new List<CoreFile>();for(int i=0;i<files.Length;i++){token.ThrowIfCancellationRequested();string f=files[i];try{string output=await Task.Run(()=>owner.Engine.ConvertFile(f,format,token));rows.Add(new CoreFile(){Source=f,State="Done",Outputs=new[]{output}});}catch(OperationCanceledException){throw;}catch(Exception ex){rows.Add(new CoreFile(){Source=f,State="Failed",Outputs=new string[0],Detail=ex.Message});}bar.Value=100.0*(i+1)/files.Length;}result=new CoreResult(){Files=rows.ToArray()};}
   outputs=result.Files.SelectMany(f=>f.Outputs??new string[0]).ToList();owner.RecordCore(result,format);running=false;Complete(result,false);
  }catch(OperationCanceledException){running=false;Complete(null,true);}catch(Exception ex){running=false;Frame("这次未能完成。",ex.Message);body.Children.Add(Button("重试 / 换格式",()=>ShowFiles(files),true));}finally{cancel.Dispose();cancel=null;}
 }
 void Complete(CoreResult result,bool canceled){int success=result==null?0:result.Files.Count(f=>f.State=="Done"||f.State=="Skipped"),failed=result==null?0:result.Files.Length-success;Frame(canceled?"已取消。":failed==0?"好了，文件已就位。":"部分文件需要检查。",canceled?"已经完成的结果会保留。":"成功 "+success+" / 失败 "+failed+" · "+outputs.Count+" 个输出");var badge=new Border(){Background=Brush(failed==0?"#EDF9F3":"#FFF5E9"),CornerRadius=new CornerRadius(16),Padding=new Thickness(18),Margin=new Thickness(0,10,0,18)};badge.Child=Text(canceled?"—":failed==0?"✓  转换完成":"!  请查看下方详情",20,failed==0?"#34936A":"#B47D34");body.Children.Add(badge);
