 void Options(){Frame("按你的习惯转换。","选项只对对应类型生效；保存后返回格式选择。");var quality=Input("图片质量 1–100",recipe.Quality.ToString());var width=Input("图片宽度 / 0 保持原尺寸",recipe.MaxWidth.ToString());var dpi=Input("输出 DPI / 0 保持",recipe.Dpi.ToString());var rotation=new ComboBox(){ItemsSource=new[]{"不旋转","顺时针 90°","旋转 180°","逆时针 90°"},SelectedIndex=recipe.Rotate/90,Margin=new Thickness(0,5,0,12),Padding=new Thickness(8)};body.Children.Add(Text("图片旋转",11,"#8291A8"));body.Children.Add(rotation);var gray=Check("转为灰度",recipe.Grayscale);var strip=Check("移除图片元数据",recipe.StripMetadata);var merge=Check("将本批结果合并为一个 PDF（目标为 PDF）",recipe.Merge);var combine=Check("将本批文件合成一个压缩包",recipe.Combine);var compress=Check("PDF 使用电子书压缩档",recipe.Compress);var dates=Check("保留原文件日期",recipe.KeepDates);var split=Check("PDF 每页拆分为独立文件",recipe.Split);var longimage=Check("PDF 页面拼接为长图",recipe.LongImage);var removebg=Check("去除图片纯色背景",recipe.RemoveBackground);var mute=Check("视频移除音轨",recipe.RemoveAudio);var hardware=Check("优先使用硬件编码",recipe.Hardware);var frames=Check("视频导出全部帧（PNG / JPG）",recipe.Frames);var videoHeight=Input("视频最大高度 / 0 保持",recipe.VideoHeight.ToString());var bitrate=Input("有损音频码率 kbps / 0 默认",recipe.AudioBitrate.ToString());var pages=Input("PDF 页码 / 例如 1-3,5 / 留空全部",recipe.Pages);var pattern=Input("命名规则 / {name} {date} {index}",recipe.NamePattern);body.Children.Add(Button("保存并返回",()=>{int q,w,d;if(!Int32.TryParse(quality.Text,out q)||q<1||q>100||!Int32.TryParse(width.Text,out w)||w<0||w>30000||!Int32.TryParse(dpi.Text,out d)||d<0||d>1200){MessageBox.Show("请检查质量、宽度和 DPI 的数值。");return;}if(pattern.Text.IndexOfAny(Path.GetInvalidFileNameChars())>=0){MessageBox.Show("命名规则包含非法文件名字符。");return;}recipe.Quality=q;recipe.MaxWidth=w;recipe.Dpi=d;recipe.Rotate=rotation.SelectedIndex*90;recipe.Grayscale=gray.IsChecked==true;recipe.StripMetadata=strip.IsChecked==true;recipe.Merge=merge.IsChecked==true;recipe.Combine=combine.IsChecked==true;recipe.Compress=compress.IsChecked==true;recipe.KeepDates=dates.IsChecked==true;int vh