 async void Engines(){Frame("更多格式，真实可用。","依赖安装前显示下载与磁盘大小，下载会校验 SHA-256。");body.Children.Add(Text(Backend.Ready?Backend.Catalog.Formats.Count(f=>f.Id!="folder")+" 种格式定义 · "+Backend.Catalog.Engines.Count(e=>e.Available)+" 个引擎就绪":"内核尚未就绪："+Backend.Failure,13,"#407CE8"));if(!Backend.Ready){body.Children.Add(Button("重新检测",async()=>{await Backend.Initialize(owner.Pref);Engines();}));return;}
  foreach(var group in Backend.Catalog.Formats.GroupBy(f=>Backend.Category(f.Category))){var line=Text(group.Key+"  ·  "+String.Join(" / ",group.Take(12).Select(f=>f.Name))+(group.Count()>12?" …":""),11,"#768AA7");line.Margin=new Thickness(0,12,0,0);body.Children.Add(line);}
  body.Children.Add(Text("",12,"#8291A8"));try{var packages=await Task.Run(()=>Backend.Packages());foreach(var package in packages){var p=package;var row=new StackPanel(){Margin=new Thickness(0,7,0,12)};row.Children.Add(Text(p.Id.ToUpperInvariant(),14,"#3B4F70"));row.Children.Add(Text("下载 "+MainWindow.Size(p.Download)+" · 磁盘约 "+MainWindow.Size(p.Disk),11,"#8291A8"));row.Children.Add(Button(p.Installed?"重新安装 / 校验更新":"安装引擎",()=>Install(p),true));body.Children.Add(row);}}catch(Exception ex){body.Children.Add(Text(ex.Message,11,"#BA5C5C"));}
  var engines=Text(String.Join("\n",Backend.Catalog.Engines.Select(e=>(e.Available?"✓ ":"○ ")+e.Name+(!e.Available?" · 未安装":""))),11,"#8291A8");engines.Margin=new Thickness(0,15,0,15);body.Children.Add(engines);body.Children.Add(Button("返回",Home));
 }
 async void Install(CorePackage p){if(running)return;if(!p.Available){MessageBox.Show("此平台没有可下载的引擎包。");return;}running=true;cancel=new CancellationTokenSource();Frame("正在安装 "+p.Id,"下载 "+MainWindow.Size(p.Download)+" · 磁盘约 "+MainWindow.Size(p.Disk));var progress=new ProgressBar(){Height=7,Minimum=0,Maximum=100,Foreground=Brush("#407CE8"),Margin=new Thickness(0,20,0,20)};body.Children.Add(progress);body.Children.Add(Button("取消下载",()=>cancel.Cancel()));try{await Task.Run(()=>Backend.Install(p.Id,cancel.Token,v=>Dispatcher.BeginInvoke(new Action(()=>progress.Value=v*100))));await Backend.Initialize(owner.Pref);running=false;Engines();}catch(OperationCanceledException){running=false;Home();}catch(Exception ex){running=false;Frame("引擎安装未完成",ex.Message);body.Children.Add(Button("返回",Home));}finally{cancel.Dispose();cancel=null;}}
 public void Stop(){if(cancel!=null)cancel.Cancel();Backend.Shutdown();preview=true;Close();}
}
